import{_ as s,C as n,c as r,o as i,j as t,ae as d,a,G as l}from"./chunks/framework.CliRSA9F.js";const b=JSON.parse('{"title":"Plan a Podcast Before Launch","description":"Plan a podcast before it is live, complete launch readiness, and connect your published show without starting over.","frontmatter":{"description":"Plan a podcast before it is live, complete launch readiness, and connect your published show without starting over."},"headers":[],"relativePath":"getting-started/pre-launch-planning.md","filePath":"getting-started/pre-launch-planning.md"}'),c={name:"getting-started/pre-launch-planning.md"},p={id:"plan-a-podcast-before-launch",tabindex:"-1"};function h(u,e,g,f,y,m){const o=n("Badge");return i(),r("div",null,[t("h1",p,[e[0]||(e[0]=a("Plan a Podcast Before Launch ",-1)),l(o,{type:"info",text:"Ready soon",class:"soon"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#plan-a-podcast-before-launch","aria-label":'Permalink to "Plan a Podcast Before Launch <Badge type="info" text="Ready soon" class="soon" />"'},"​",-1))]),e[3]||(e[3]=d('<div class="info custom-block"><p class="custom-block-title">Not on your account yet?</p><p>Pre-launch planning is rolling out gradually and will be available to every account soon. If you don&#39;t see <strong>Design your new podcast</strong> in your podcast list yet, it hasn&#39;t reached your account.</p></div><p>You can start with a draft podcast before it has an RSS feed or a platform listing. Use it to develop your positioning, choose keywords, research competitors, and prepare episodes. A draft uses one of your plan&#39;s podcast slots; normal keyword, competitor, and Planner limits still apply.</p><h2 id="create-a-draft" tabindex="-1">Create a draft <a class="header-anchor" href="#create-a-draft" aria-label="Permalink to &quot;Create a draft&quot;">​</a></h2><p>From your podcast list, choose <strong>Design your new podcast</strong> and enter its title. Its home opens as <strong>Design</strong>, with a launch-readiness checklist instead of live performance statistics.</p><ol><li>Save a title and description explaining who the show is for and what it covers.</li><li>Work through <a href="/features/positioning.html">Positioning</a> and select your topics.</li><li>Add at least one show keyword in <a href="/features/keyword-strategy.html">Keyword Strategy</a>.</li><li>Open the <a href="/features/planner.html">Planner</a> to prepare at least one episode.</li><li>Add at least one competitor to establish the market you want to enter.</li></ol><p>Draft details, positioning, and a show keyword unlock the planning and competitor steps. Follow the checklist if a section is locked.</p><p>While a podcast is a draft, the sidebar is simplified to the areas you can use before launch. <strong>Traction</strong>, <strong>AI Visibility</strong>, <strong>Social Publishing</strong>, <strong>PR &amp; Media Coverage</strong>, and <strong>Charts</strong> are hidden because they rely on a live show. <strong>Competition</strong> appears locked until you complete your draft details, positioning, and keywords. You can upload and crop a cover image, but a cover is optional for connecting your live show.</p><h2 id="understand-launch-readiness" tabindex="-1">Understand launch readiness <a class="header-anchor" href="#understand-launch-readiness" aria-label="Permalink to &quot;Understand launch readiness&quot;">​</a></h2><p>The percentage measures completed setup steps. It is not your Visibility Score and does not predict audience size or search performance. A draft has no live rankings, reviews, distribution results, or published feed episodes yet. Those views become relevant after you connect the actual show.</p><p>Free accounts can hold up to three active planned episodes; paid plans unlock AI Producer and AI suggestions (episode keywords are available on every plan). Draft planning does not remove those restrictions.</p><h2 id="connect-the-published-podcast" tabindex="-1">Connect the published podcast <a class="header-anchor" href="#connect-the-published-podcast" aria-label="Permalink to &quot;Connect the published podcast&quot;">​</a></h2><p>Publish through your podcast host and get the show listed on Apple Podcasts. Once the required setup steps are complete, choose <strong>Connect live podcast</strong> on Design and select the correct live show from the catalog.</p><p>Connecting keeps your existing workspace, including the strategy and planned episodes, and adds the live show&#39;s data as it becomes available. Use this action instead of adding the same show as a second podcast. If PodSEO says you already track it, resolve the duplicate workspace before connecting.</p><p>PodSEO&#39;s draft is a planning workspace; creating it or connecting a listing does not publish audio to your host. After launch, continue with <a href="/getting-started/first-steps.html">First Steps</a> and <a href="/getting-started/workflow.html">the PodSEO workflow</a>.</p>',14))])}const v=s(c,[["render",h]]);export{b as __pageData,v as default};
